from math import log, floor
from functools import lru_cache

class ChessboardSolver:
    def __init__(self, k, deleted_squares):
        self.k = k
        self.deleted_squares = set(deleted_squares)

    def count_board_squares(self):
        @lru_cache(None)
        def dp(x, y, depth):
            if depth > self.k or (x, y) in self.deleted_squares or (depth, (x, y)) in dp_cache:
                return 0
            if depth == 1:
                return 1 if (x, y) not in self.deleted_squares else 0

            count = 0
            for dx, dy in [(2, 1), (2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2), (-2, 1), (-2, -1)]:
                if abs(dx) + abs(dy) <= 1:
                    count += dp(x + dx, y + dy, depth - 1)
            dp_cache[(depth, (x, y))] = count % 1000000007
            return dp_cache[(depth, (x, y))]

        dp_cache = {(1, (0, 0)) + (0, 0): 1}
        count = dp(0, 0, floor(log(max(1, self.k), 2)) + 1)
        return count % 1000000007

