# Function to calculate F(n) modulo 10^18
def F(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a = [0, 1]
    for i in range(2, n + 1):
        a.append((a[-1] + a[-2]) % (10**18))
    return a[n]

