def find_special_values(n, a, d):
    # Compute the recursive relation for Fibonacci numbers
    def fibonacci(n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            fib = [0, 1]
            for i in range(2, n + 1):
                fib.append(fib[-1] + fib[-2])
            return fib[-1]

    # Check the condition for any b and e that we might find
    def check_condition(b, e, d):
        for i in range(n):
            if str(a + i * d)[-18:] in str(fibonacci(b + i * e)):
                return b, e
        return -1

    # Initial conditions
    h, w = 0, 1
    x = [a]
    for i in range(n - 2):
        x.append(x[-1] + d)

    remaining_length = 18 * n
    i = 0
    A = [a]
    while i <= remaining_length:
        j = 0
        b = x[j] + i * d
        while j <= remaining_length:
            if str(b)[-18:] not in str(fibonacci(b + i * w)):
                break
            j += 1
        if j - i >= remaining_length and i < n:
            break
        if j - i >= remaining_length:
            h, w = i, w
        i += 1
    b, e = check_condition(b, a, d)
    if b == -1:
