from functools import lru_cache

def calculate_score(sequence, parts_count, modulo):
    @lru_cache(maxsize=None)
    def backtrack(start, end):
        if end == len(sequence):
            return 0
        min_score = float('inf')
        for split in range(start, min(end + 1, parts_count + 1)):
            score = (sum(sequence[start:split]) % modulo + backtrack(split, end) - sum(sequence[split:])) % modulo
            min_score = min(min_score, score)
        return min_score

    return backtrack(0, len(sequence))

