def count_knights_steps(k, deleted_squares):
    deleted_cells = [(-1, -1)]
    for i, j in deleted_squares:
        i, j = abs(i), abs(j)
        if i > 1:
            deleted_cells.extend([(j, 1-i), (-j, 1-i)])
        if j > 1:
            deleted_cells.extend([(1-i, j), (3-j, j)])
    deleted_cells = set(deleted_cells)

    all_cells = set([(x, y) for x in range(-15, 16) for y in range(-15, 16) if (x, y) != (0, 0)])
    available_cells = all_cells - deleted_cells

    if k == 0 or len(available_cells) == 0:
        return len(available_cells)

    for j in range(1, k + 1):
        available_cells = {a // (j+1) for a in available_cells}

    return len(available_cells) % 1000000007

