import math

def find_smallest_time(tree, d, u, v, s, time):
    if tree[u] == v:
        return "Never"
    for edge in tree:
        parent, child, weight = edge
        if child != v:
            break
    time += weight
    if tree[parent][0] == parent:
        # Child is a descendant of its parent
        # if time is divisible by child + 1, it can be visited,
        # else it cannot be visited as the time to reach from parent is less than its velocity
        if time % (child + 1) == 0 or u == 0 or (time % (child + 1) > s or u != 0):
            return f"{time} {s}"
        else:
            return "Never"
    else:
        # Child is an ancestor of its parent
        # If the time difference between time + weight is less than or equal to s, it can be visited
        if (time + weight) <= s or child == 0:
            return f"{time} {s}"
        else:
            return "Never"

