        self.val = val
        self.left = left
        self.right = right

def find_valid_edges(n, colors, edges):
    tree = [TreeNode(i) for i in range(n)]
    for i in range(n-1):
        u, v = edges[i+1]
        tree[u-1].left = tree[v-1]
        tree[v-1].right = tree[u-1]

    def dfs(node):
        nonlocal target
        if not node.left and not node.right:
            return
        if node.left:
            tree[node].val = target
        else:
            target += tree[node].val
        dfs(node.left)
        dfs(node.right)

    def dfs2(node):
        if not node.left and not node.right:
            return
        if node.left:
            tree[node].val += tree[node.left].val + dfs2(node.left)
            if node.left.left or node.left.right:
                target = node.val + dfs2(node.left) * 2
        else:
            target += dfs2(node.left)
            tree[node].val += tree[node.right].val + dfs2(node.right) * 2 - target
            if node.right.left or node.right.right:
                target = target + node.val + dfs2(node.right)

    target = 0
    dfs(0)
    dfs2(0)
    return [tree[i].val for i in range(n-1)]

