import sympy

def is_fibonacci_substring(n, s, base):
    """ Check if the number's last 18 digits contains a substring of length n from s """
    number = long(s)
    hundreds = pow(base, 18)
    for i in range(n):
        last_18 = (number * pow(base, 18)) % hundreds
        number = last_18
    return str(long(s)) in str(last_18)

def find_fibonacci_terms(a, d, n, base):
    """ Find two integers b and e that satisfy the conditions """
    low = 0
    high = 10**6
    while low < high:
        mid = (low + high) // 2
        if is_fibonacci_substring(n, str(a + (mid - 1) * d).zfill(18), base):
            return mid, base**(mid - 1 // d)
        elif is_fibonacci_substring(n, str(a + (mid + 1) * d).zfill(18), base):
            return (mid + 1) // d, base**(mid + 1 // d - 1)
        elif mid == 0:
            break
        elif mid % 2 == 0:
            low = mid + 1
        else:
            high = mid - 1
    return -1

