from collections import defaultdict
from typing import List, Tuple

def build_graph(n: int, dislikes: List[Tuple[int]]) -> defaultdict:
    graph = defaultdict(List)
    for (a, b) in dislikes:
        graph[a - 1].append(b - 1)
        graph[b - 1].append(a - 1)
    return graph

def dfs(graph: defaultdict, in_degree: List[int], visited: List[int]) -> int:
    components = 0
    for i in range(len(graph)):
        if visited[i]:
            continue

        all_black_hat_in_node = True
        stack = [i]
        while stack:
            node = stack.pop()
            if not in_degree[node]:
                all_black_hat_in_node = False
                break

            visited[node] = 1
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    stack.append(neighbor)

        if all_black_hat_in_node:
            components += 1

    return components

def solve(n: int, m: int, dislikes: List[Tuple[int]]) -> List[int]:
    graph = build_graph(n, dislikes)
    in_degree = [0] * n
    for i in range(n):
        for nei in graph[i]:
            in_degree[nei] += 1

    initial_singular_comp = dfs(graph, in_degree, [0] * n)
    answer = [initial_singular_comp]
    for _ in range(m):
        in_degree = [0] * n
        for i in range(n):
            for nei in graph[i]:
                in_degree[nei] += 1

        answer.append(initial_singular_comp)
        initial_singular_comp = dfs(graph, in_degree, [0] * n)

    return answer

