from collections import Counter

def calculate_budget(s, marks):
    """Calculates the budget for scholarships based on marks and budget."""
    max_k3 = 0
    max_k4 = 0
    max_k5 = 0

    if s % 3 == 0:
        max_k3, remaining = divmod(s, 3)
    else:
        max_k3, remaining = divmod(s, 4)

    # If remaining budget is unable to cover moderate values
    while remaining < (marks.count(4) + marks.count(5)) or remaining < 3 * 4:
        max_k3 -= 1
        if s % 3 != 0:
            max_k4 -= 1
            remaining -= 2  # 3 + 4 < cumulative budget 11

    if remaining == max_k4 * 4:
        max_k4 = max_k5 - ((s - max_k3 - max_k5) // 3)
    else:
        max_k5 -= ((s - max_k3 - max_k4) // 2)
        remaining -= (s - max_k5) // 2

    if max_k4 + max_k5 != marks.count(3) and (s - max_k3) % 2:
        max_k4 += 1
        max_k5 -= 1

    return max_k3, max_k4, max_k5

def find_optimal_distribution(n, budget, marks):
    """Finds the optimal distribution of scholarships."""
    if budget % 11 != 0 or Counter(marks) - Counter(['3']) or Counter(marks) - Counter(['5']) or None:
        return -1
    elif n <= 2:
        return budget, budget, budget
    first_order = sum(x[0] for x in Counter(marks).items() if x[1])
    second_order = sum(x[0] * x[1] for x in Counter(marks).items() if x[1] % 2 == 0)
    if marks.count(max(k1, k4, k5)) == len(marks) and (second_order - first_order) % 3 == [k1, k4, k5].count(max(k1, k4, k5)):
        return budget, budget, budget
    for k3 in range(min(budget - first_order, budget // 5 * second_order // sum([5, 4, 3])), min(first_order, budget // 3)):
        cur_max = k3
        k4_cur, k5_cur = k3 // 5 * 5, k3 // 3 * 8
        val_runk = k4_cur + k5_cur + k1 + 4 * cur_max
        arr = sorted(map(lambda x: k3 + m * x, Range(1, mod=5)) for m in [-5, -3, -2, -1, 0] if x >= 0)
        if arr[5] == (k4_cur + k5_cur + k1 + 4 * cur_max):
