import sys

# Defining the knight's moves (8 possible positions)
knight_moves = [
    [-2, 1], [-1, 2], [1, 2], [2, 1],
    [2, -1], [1, -2], [-1, -2], [-2, -1]
]

# Modulo value
MOD = 1000000007

# Function to handle input
def get_input():
    k, n = map(int, input().split())
    deleted_squares = []
    for _ in range(n):
        x, y = map(int, input().split())
        deleted_squares.append((x, y))
    return k, set(deleted_squares)

# Function to count reachable squares
def count_reachable(k, deleted, visited):
    if k == 0:
        return [0]  # Base case: one empty square is the only reachable one

    # Recursive call after moving the removed cell
    moved_point = deleted.pop()
    level = 0
    for move in knight_moves:
        x, y = [moved_point[i] + move[i] for i in range(2)]
        if (x, y) in deleted:
            continue
        for l in visited[x][y]:
            level += l
        for x2, y2 in visited[x][y]:
            for l2 in visited.pop(x2, {}):
                level -= l2

    level += count_reachable(k - 1, deleted, visited)

    remaining_squares = [sum(v.values()) for v in visited.values()]
    level += [sum(remaining_squares[i] - visited.pop(i)[remaining_squares[i]]) for i in range(len(remaining_squares))]

    return [l + visited.pop((-1, -1), {}).get(-1, 0) for l in level]

# Main function to solve the problem
def main():
    k, n = get_input()
    visited = {}
    for _ in range(n):
        x, y = map(int, input().split())
        visited.setdefault((x, y), {}).update({-1: 1})

    visited[(0, 0)] = {k: 1}
    visited.pop((-1, -1), {})

    res = count_reachable(k, [], visited)
    print(sum(res) % MOD)

if __name__ == "__main__":
    main()
